if(process.env.FIREBASE_PROJECT_ID!=='demo-mongo-audit'||process.env.FIREBASE_AUTH_EMULATOR_HOST!=='127.0.0.1:9298')throw Error('Isolated audit emulator required.');
let mongo,client,database,auth,adminApp,store,app,http,frontend,browser;const ids={};const run=Date.now().toString(36);
async function person(id,role,extra={}){const uid='lifecycle_'+run+'_'+id,email=id+'-'+run+'-lifecycle@demo.test';try{await auth.createUser({uid,email,password:'DemoPassword123!'});}catch(error){if(error.code!=='auth/uid-already-exists'&&error.code!=='auth/email-already-exists')throw error;await auth.updateUser(uid,{disabled:false});}await database.collection('users').insertOne({_id:uid,name:id,email,role,accountStatus:'active',...extra});ids[id]=uid;return uid;}
async function token(id){const r=await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=fake',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:id.includes('@')?id:id+'-'+run+'-lifecycle@demo.test',password:'DemoPassword123!',returnSecureToken:true})});return (await r.json()).idToken;}
const actor=()=>({uid:ids.manager,role:'super_admin'});
before(async()=>{mongo=await MongoMemoryReplSet.create({replSet:{storageEngine:'wiredTiger'}});({client,database}=await connectDatabase(mongo.getUri('lifecycle_scope_audit')));const f=firebaseAdmin();auth=f.auth;adminApp=f.app;({store,app}=createApp({database,client,auth,demo:true,origins:['http://127.0.0.1:5053']}));http=app.listen(3003);frontend=express().use(express.static(fileURLToPath(new URL('../..',import.meta.url)))).listen(5053,'127.0.0.1');await person('manager','super_admin');await person('central-accounts','accounts',{scope:'institution',departmentId:null});await person('central-library','library',{scope:'institution'});
 for(const code of ['ISE','CSE','ME']){await database.collection('departments').insertOne({_id:'dep_'+code,code,name:code,codeKey:code.toLowerCase(),nameKey:code.toLowerCase(),status:'active'});for(const role of ['office','hod','mentor','subject_faculty'])await person(code+'-'+role,role,{scope:'department',departmentId:'dep_'+code,department:code,facultyId:code+'-'+role});await database.collection('departmentWorkflows').insertOne({_id:'dep_'+code,officeId:ids[code+'-office'],hodId:ids[code+'-hod'],accounts:ids['central-accounts'],library:ids['central-library']});const uid=await person(code+'-student','student',{scope:'department',departmentId:'dep_'+code,department:code});const s={name:code+' Student',email:code+'-student-'+run+'-lifecycle@demo.test',usn:'AUDIT'+code,department:code,departmentId:'dep_'+code,scheme:'2022',semester:5,section:'A',mentorId:ids[code+'-mentor'],accountStatus:'active',offeringIds:['off_'+code],teacherIds:[ids[code+'-subject_faculty']]};await database.collection('students').insertOne({_id:uid,...s});await database.collection('offerings').insertOne({_id:'off_'+code,department:code,departmentId:'dep_'+code,scheme:'2022',semester:5,section:'A',subjectCode:'TEST501',subjectName:'Test',teacherId:ids[code+'-subject_faculty'],active:true});await database.collection('enrollments').insertOne({_id:uid+'__off_'+code,studentId:uid,offeringId:'off_'+code,teacherId:ids[code+'-subject_faculty'],active:true});await syncOfficeSearchIndex(store,uid);}
});
after(async()=>{await browser?.close();if(http)await new Promise(resolve=>http.close(resolve));if(frontend)await new Promise(resolve=>frontend.close(resolve));await client?.close();await adminApp?.delete();await mongo?.stop();});
test('shared Accounts routes all three departments while Offices and searches remain isolated',async()=>{for(const code of ['ISE','CSE','ME']){const uid=ids[code+'-student'],plan=await enrollmentPlan(store,uid);assert.equal(plan.items.accounts.approverId,ids['central-accounts']);assert.equal(plan.officeId,ids[code+'-office']);const search=await searchOfficeStudents(store,ids[code+'-office'],{term:'student'});assert.equal(search.count,1);assert.equal(search.rows[0].department,code);const forged=await searchOfficeStudents(store,ids[code+'-office'],{term:ids[(code==='ME'?'ISE':'ME')+'-student']});assert.equal(forged.count,0);}
 const original=await database.collection('departmentWorkflows').findOne({_id:'dep_ME'});await database.collection('departmentWorkflows').updateOne({_id:'dep_ME'},{$set:{officeId:ids['ISE-office']}});await assert.rejects(()=>enrollmentPlan(store,ids['ME-student']),/Office/);await database.collection('departmentWorkflows').replaceOne({_id:'dep_ME'},original);
});
test('department final issuance, rejection/resubmission and historical shared Office references survive configuration changes',async()=>{await database.collection('departments').updateOne({_id:'dep_CSE'},{$set:{hodId:ids['CSE-hod']}});const code='CSE',uid=ids[code+'-student'],created=await submitRequest(store,{uid,role:'student'},'lifecycle_workflow'),id=created.id;await requestAction(store,{uid:ids['CSE-subject_faculty'],role:'subject_faculty'},id,{action:'stage1',approvalId:'subject_off_CSE',decision:'rejected',reason:'Assignment missing'});await requestAction(store,{uid,role:'student'},id,{action:'resubmit'});for(const [key,item]of Object.entries((await database.collection('noDueRequests').findOne({_id:id})).approvalItems))await requestAction(store,{uid:item.approverId,role:item.approverType},id,{action:'stage1',approvalId:key,decision:'approved'});for(const role of ['mentor','hod'])await requestAction(store,{uid:ids['CSE-'+role],role},id,{action:role,decision:'approved'});await assert.rejects(()=>requestAction(store,{uid:ids['ME-office'],role:'office',scope:'department',departmentId:'dep_ME'},id,{action:'issue'}),/Office|department/);await requestAction(store,{uid:ids['CSE-office'],role:'office',scope:'department',departmentId:'dep_CSE',name:'CSE Office'},id,{action:'issue'});assert.equal((await database.collection('noDueRequests').findOne({_id:id})).status,'issued');assert.ok(await database.collection('hallTickets').findOne({_id:id}));});
test('deactivation preserves records, state-aware login and stale tokens block; reactivation retains UID/password/history',async()=>{const uid=ids['ISE-student'],bearer=await token('ISE-student'),before={};for(const c of ['enrollments','students','noDueRequests','marks'])before[c]=await database.collection(c).find({}).toArray();await accountRemoval({database,client,auth,actor:actor(),uid,confirmation:'DEACTIVATE',reason:'Temporary leave'});assert.equal((await auth.getUser(uid)).disabled,true);await assert.rejects(()=>loginIdentity(database,'AUDITISE'),/deactivated.*department administrator/);const r=await request(app).get('/api/auth/profile').set('Authorization','Bearer '+bearer);assert.ok([401,403].includes(r.status));for(const c of ['enrollments','noDueRequests','marks'])assert.deepEqual(await database.collection(c).find({}).toArray(),before[c]);const result=await accountExit({database,client,auth,actor:actor(),input:{action:'reactivate',kind:'student',uid,confirmation:'REACTIVATE'},restoreStudent:async()=>{throw Error('Temporary deactivation must preserve mappings');}});assert.equal(result.accountStatus,'active');assert.ok(await token('ISE-student'));assert.equal((await loginIdentity(database,'AUDITISE'))._id,uid);assert.deepEqual(await database.collection('enrollments').find({}).toArray(),before.enrollments);});
test('institutional exit archives active records and reserves identity without overwriting marks or completed history',async()=>{const uid=ids['ME-student'];await database.collection('marks').insertOne({_id:'exit-mark',studentId:uid,scores:{ia1:23}});await database.collection('noDueRequests').insertOne({_id:'exit-history',studentId:uid,status:'issued',officeId:ids['ME-office']});const mark=await database.collection('marks').findOne({_id:'exit-mark'}),history=await database.collection('noDueRequests').findOne({_id:'exit-history'});const call=()=>accountRemoval({database,client,auth,actor:actor(),uid,confirmation:'EXIT',institutionalExit:true,reason:'Transferred'});await call();await call();assert.equal((await database.collection('users').findOne({_id:uid})).accountStatus,'exited');assert.equal(await database.collection('enrollments').countDocuments({studentId:uid,active:true}),0);assert.deepEqual(await database.collection('marks').findOne({_id:'exit-mark'}),mark);assert.deepEqual(await database.collection('noDueRequests').findOne({_id:'exit-history'}),history);await assert.rejects(()=>loginIdentity(database,'AUDITME'),/no longer active/);await assert.rejects(()=>accountExit({database,client,auth,actor:actor(),input:{action:'reactivate',kind:'student',uid,confirmation:'REACTIVATE'}}));assert.equal(await database.collection('accountExitEvents').countDocuments({uid,action:'ACCOUNT_INSTITUTIONAL_EXIT'}),1);});
test('nonexistent identities and institutional deactivation produce exact public messages',async()=>{await assert.rejects(()=>loginIdentity(database,'MISSING-AUDIT'),/No user exists with this Email \/ USN \/ Employee ID/);await database.collection('users').updateOne({_id:ids['central-accounts']},{$set:{accountStatus:'inactive'}});await assert.rejects(()=>loginIdentity(database,'central-accounts-'+run+'-lifecycle@demo.test'),/deactivated.*institution administrator/);await database.collection('users').updateOne({_id:ids['central-accounts']},{$set:{accountStatus:'active'}});const wrong=await request(app).post('/api/auth/login').send({identifier:'CSE-student-'+run+'-lifecycle@demo.test',password:'wrong'});assert.equal(wrong.body.error.message,'Email / USN / Employee ID or password is incorrect.');});
test('hard delete blocks history with exit advice and is restricted to Super Admin; safe dummy is removable',async()=>{const bearer=await token('manager'),call=(path,body)=>request(app).post('/api/admin/accounts/'+path).set('Authorization','Bearer '+bearer).send(body);const pre=await call('delete-preflight',{accountIds:[ids['ME-student']]});assert.equal(pre.status,200);assert.match(pre.body.rows[0].reason,/Permanent Institutional Exit/);const uid=await person('unused','student',{scope:'department',departmentId:'dep_ME'});const result=await call('permanent-delete',{accountIds:[uid],confirmation:true,requestId:'lifecycle-safe-delete'});assert.equal(result.body.deleted,1,JSON.stringify(result.body));assert.equal(await database.collection('users').findOne({_id:uid}),null);await assert.rejects(()=>auth.getUser(uid));});
test('five-row bulk exit preview and explicit operation preserve identities; templates contain one column only',async()=>{const identifiers=[];for(let i=0;i<5;i++){const uid=await person('bulk'+i,'student',{scope:'department',departmentId:'dep_ME'});await database.collection('students').insertOne({_id:uid,usn:'LIFEBULK'+i,departmentId:'dep_ME'});identifiers.push('LIFEBULK'+i);}const bearer=await token('manager'),call=(path,body)=>request(app).post('/api/admin/accounts/'+path).set('Authorization','Bearer '+bearer).send(body);const preview=await call('exit-preview',{kind:'student',action:'institutional-exit',identifiers});assert.equal(preview.body.eligible,5);assert.ok(preview.body.rows.every(r=>r.reason==='Eligible for institutional exit.'));const done=await call('bulk-status',{accountIds:preview.body.rows.map(r=>r.uid),targetStatus:'exited',confirmation:'EXIT',reason:'Left institution',requestId:'lifecycle-five-row-exit'});assert.equal(done.body.succeeded,5,JSON.stringify(done.body));for(const uid of preview.body.rows.map(r=>r.uid)){assert.equal((await auth.getUser(uid)).disabled,true);assert.equal((await database.collection('users').findOne({_id:uid})).accountStatus,'exited');}assert.equal((await readFile('../templates/student-exit.csv','utf8')).trim(),'usn');assert.equal((await readFile('../templates/faculty-exit.csv','utf8')).trim(),'employee_id');});

test('scope migration is narrow and idempotent, reuses Accounts and creates no Office for future empty departments',async()=>{
 const {planRoleScopes,migrateRoleScopes}=await import('../src/services/role-scope-migration.js');
 await database.collection('institutionPolicy').updateOne({_id:'workflow'},{$set:{accounts:ids['central-accounts']}},{upsert:true});
 await database.collection('departments').insertOne({_id:'dep_FUTURE',code:'FUTURE',codeKey:'future',nameKey:'future',name:'Future',status:'active'});
 const protectedNames=['marks','students','enrollments','noDueRequests','approvals','hallTickets','offerings'],before=Object.fromEntries(await Promise.all(protectedNames.map(async n=>[n,await database.collection(n).find({}).toArray()])));
 const options={database,client,auth,actor:actor(),provisioner:{dispatch:()=>{throw Error('Existing Offices must be reused');}}};
 const first=await migrateRoleScopes({...options,apply:true});assert.equal(first.accounts.uid,ids['central-accounts']);assert.equal(first.offices.length,3);assert.ok(first.offices.every(o=>o.action==='KEEP'));const repeat=await migrateRoleScopes({...options,apply:true});assert.equal(repeat.accounts.changed,false);assert.equal(await database.collection('users').countDocuments({role:'office',departmentId:'dep_FUTURE'}),0);assert.equal(await database.collection('departmentWorkflows').findOne({_id:'dep_FUTURE'}),null);assert.equal((await database.collection('users').findOne({_id:ids['central-accounts']})).departmentId,null);for(const n of protectedNames)assert.deepEqual(await database.collection(n).find({}).toArray(),before[n]);
 const users=await database.collection('users').find({}).toArray(),departments=await database.collection('departments').find({}).toArray(),workflows=await database.collection('departmentWorkflows').find({}).toArray();assert.throws(()=>planRoleScopes({users,departments,workflows:[...workflows,{_id:'ambiguous',accounts:'other'}],policy:{accounts:ids['central-accounts']}}),/ambiguous/);
});

