test('faculty institutional exit archives its teaching only, removes current mentoring and retains marks and identity references',async()=>{
 const uid=await person('departing-faculty','subject_faculty',{scope:'department',departmentId:'dep_ME',department:'ME',facultyId:'EXIT-FAC',isMentor:true}),student=await person('mentee-exit','student',{scope:'department',departmentId:'dep_ME',department:'ME'});await database.collection('students').insertOne({_id:student,usn:'EXITMENTEE',department:'ME',departmentId:'dep_ME',mentorId:uid,accountStatus:'active'});await database.collection('offerings').insertOne({_id:'exit-faculty-offering',teacherId:uid,active:true});await database.collection('enrollments').insertMany([{_id:'exit-faculty-own',studentId:student,teacherId:uid,offeringId:'exit-faculty-offering',mentorId:uid,active:true},{_id:'exit-faculty-other',studentId:student,teacherId:ids['ME-subject_faculty'],offeringId:'off_ME',mentorId:uid,active:true}]);await database.collection('marks').insertOne({_id:'exit-faculty-marks',studentId:student,teacherId:uid,scores:{ia1:21}});const before=await database.collection('marks').findOne({_id:'exit-faculty-marks'});
 await accountRemoval({database,client,auth,actor:actor(),uid,confirmation:'EXIT',institutionalExit:true,reason:'Resigned'});assert.equal((await database.collection('offerings').findOne({_id:'exit-faculty-offering'})).active,false);assert.equal((await database.collection('enrollments').findOne({_id:'exit-faculty-own'})).active,false);const other=await database.collection('enrollments').findOne({_id:'exit-faculty-other'});assert.equal(other.active,true);assert.equal(other.mentorId,undefined);assert.equal(other.previousMentorId,uid);assert.equal((await database.collection('students').findOne({_id:student})).mentorId,undefined);assert.deepEqual(await database.collection('marks').findOne({_id:'exit-faculty-marks'}),before);assert.equal((await database.collection('users').findOne({_id:uid})).originalIdentity.facultyId,'EXIT-FAC');
});

test('missing current-department Office uses normal UID-safe provisioning once and preserves legacy Office history',async()=>{
 const {createProvisioner}=await import('../src/services/provisioning.js'),{migrateRoleScopes}=await import('../src/services/role-scope-migration.js');await database.collection('users').updateOne({_id:ids['ME-office']},{$set:{scope:'institution'},$unset:{departmentId:'',department:''}});const history=await database.collection('noDueRequests').find({}).toArray(),marks=await database.collection('marks').find({}).toArray();const options={database,client,auth,actor:actor(),provisioner:createProvisioner({db:store,auth,demo:true})};const plan=await migrateRoleScopes(options);assert.equal(plan.offices.find(o=>o.code==='ME').action,'CREATE');const applied=await migrateRoleScopes({...options,apply:true}),office=applied.offices.find(o=>o.code==='ME');assert.notEqual(office.uid,ids['ME-office']);assert.equal((await auth.getUser(office.uid)).email,'office.me@demo.test');const profile=await database.collection('users').findOne({_id:office.uid});assert.equal(profile.scope,'department');assert.equal(profile.departmentId,'dep_ME');assert.equal(profile.mustChangePassword,true);assert.equal(profile.password,undefined);const repeat=await migrateRoleScopes({...options,apply:true});assert.equal(repeat.offices.find(o=>o.code==='ME').uid,office.uid);assert.equal(await database.collection('users').countDocuments({email:'office.me@demo.test'}),1);assert.ok(await database.collection('users').findOne({_id:ids['ME-office']}));assert.deepEqual(await database.collection('noDueRequests').find({}).toArray(),history);assert.deepEqual(await database.collection('marks').find({}).toArray(),marks);
});

