 for(const code of ['ISE','CSE','ME']){const office=await database.collection('users').findOne({role:'office',scope:'department',departmentId:'dep_'+code}),bearer=await token(office.email);for(const path of ['noDueRequests','hallTickets']){const response=await request(app).post('/api/data/query').set('Authorization','Bearer '+bearer).send({path});assert.equal(response.status,200,JSON.stringify(response.body));for(const row of response.body.rows)assert.equal((await database.collection('students').findOne({_id:row.data.studentId})).departmentId,'dep_'+code);}}
 await database.collection('noDueRequests').insertOne({_id:'forged-cross-office',studentId:ids['CSE-student'],officeId:ids['ISE-office'],status:'cleared'});const bearer=await token('ISE-office'),hidden=await request(app).post('/api/data/query').set('Authorization','Bearer '+bearer).send({path:'noDueRequests'});assert.equal(hidden.status,200);assert.ok(!hidden.body.rows.some(r=>r.id==='forged-cross-office'));await database.collection('noDueRequests').deleteOne({_id:'forged-cross-office'});
